'use strict';
/* The project module owns eligibility, progress, costs and consequences. */
const LifeProjectUI=(()=>{
 const number=n=>(Number(n)||0).toLocaleString('th-TH',{maximumFractionDigits:2});
 const progress=p=>Math.max(0,Math.min(100,Math.round(Number(p)||0)));
 const focusName=id=>LifeChoices.focusCatalog.find(f=>f.id===id)?.label||id;
 function blocked(s){return s.dead||!s.accepted||!!s.calendar?.pending||!!s.outcome}
 function blockReason(s){return s.dead?'ชีวิตนี้สิ้นสุดแล้ว ยังกลับมาอ่านสิ่งที่ทำไว้ได้':!s.accepted?'เริ่มชีวิตก่อนเลือกเรื่องที่อยากทำ':s.calendar?.pending?'ตอบเหตุการณ์สำคัญก่อนเริ่มหรือยุติเรื่องที่กำลังทำ':s.outcome?'อ่านผลการตัดสินใจให้จบก่อนเริ่มหรือยุติเรื่องที่กำลังทำ':''}
 function activeStatus(a){return a.ready?'ถึงจุดที่ต้องตัดสินใจ':a.reason||a.status||(a.supported?'ค่อย ๆ เดินหน้าเมื่อเวลาผ่านไป':'พักไว้ระหว่างให้เวลากับเป้าหมายอื่น')}
 function panel(s){const report=LifeProjects.summary(s),a=report.active;return `<section class="panel project-plan" aria-label="เส้นทางระยะยาว"><div class="project-plan-heading"><div><span class="project-plan-kicker">สิ่งที่ค่อย ๆ สร้างในชีวิต</span><h2>${a?esc(a.name):'อยากทำอะไรให้สำเร็จสักเรื่อง?'}</h2>${a?`<p>บท ${a.stageNumber} / ${a.stageCount} · ${esc(a.stageTitle)}</p>`:`<p>${Ecology.profile(s).strict?'เรียนรู้ถิ่น ดูแลร่าง และสร้างเส้นทางที่กลุ่มใช้ต่อได้':'เรียนสิ่งใหม่ สร้างมุมของครอบครัว หรือทำบางอย่างให้ผู้คนรอบตัว'}</p>`}</div><button class="secondary" id="lifeProject">${a?'ติดตามเรื่องนี้':'เลือกเส้นทาง'} →</button></div>${a?`<div class="project-plan-progress"><progress max="100" value="${progress(a.progressPercent)}" aria-label="ความคืบหน้าบทนี้"></progress><span>${progress(a.progressPercent)}%</span></div><small class="project-plan-status">${esc(activeStatus(a))}${a.castName?' · ร่วมเรื่องกับ '+esc(a.castName):''}</small>`:report.paused?.length?`<small class="project-plan-status">พักไว้ ${report.paused.length} เรื่อง · กลับมาทำต่อจากบทเดิมได้</small>`:report.completed?.length?`<small class="project-plan-status">มีเรื่องที่จบแล้ว ${report.completed.length} เรื่อง · ย้อนอ่านได้ในสมุดเส้นทาง</small>`:''}</section>`}
 function bind(){if($('#lifeProject'))$('#lifeProject').onclick=open}
 function refresh(message){save();clock.reset();render();open();if(message)toast(message)}
 function requirementsText(p){const out=[];if(p.minAge)out.push('เริ่มได้เมื่อเติบโตเทียบวัย '+p.minAge+' ปี');if(p.requirements?.job)out.push('มีอาชีพประจำ');if(p.requirements?.business)out.push('มีกิจการที่ยังเปิดอยู่');if(p.focuses?.length)out.push('ให้เวลากับ '+p.focuses.map(focusName).join(' / '));return out.join(' · ')}
 function stages(a){const base=LifeProjects.catalog.find(p=>p.id===a.id),def=base?{...base,...(Ecology.projectInfo(state,a.id)||{})}:null;return (def?.stages||[]).map((stage,i)=>`<li class="${i<a.stage?'done':i===a.stage?'current':''}"><span>${i<a.stage?'✓':i+1}</span><div><b>${esc(stage.title)}</b>${i===a.stage?`<small>${esc(a.stageDescription||stage.description||'')}</small>`:''}</div></li>`).join('')}
 function open(){const s=state,report=LifeProjects.summary(s),a=report.active,locked=blocked(s),choices=LifeProjects.available(s);modal(`<div class="life-dialog project-dialog"><span class="eyebrow">อายุ ${s.age} ปี · เดือน ${(s.calendar?.quarter||0)*3+1}</span><h2>เรื่องที่คุณอยากทำให้สำเร็จ</h2><p>เลือกทำครั้งละหนึ่งเรื่อง ชีวิตจะค่อย ๆ พาไปพบคน งาน และการตัดสินใจต่อเนื่อง ผลของทางที่เลือกจะอยู่ในบันทึก</p>${locked?`<p class="life-action-note" role="status">${esc(blockReason(s))}</p>`:''}${a?`<section class="project-current"><div class="project-current-heading"><div><small>เริ่มเมื่ออายุ ${number(a.startedAge)} ปี</small><h3>${esc(a.name)}</h3></div><span>บท ${a.stageNumber} / ${a.stageCount}</span></div>${a.castName?`${a.anchored&&a.kingdomName?`<p class="life-small-note">สถานที่ของเรื่องนี้: ${esc(a.kingdomName)}</p>`:''}<p class="project-cast">ร่วมเรื่องกับ <b>${esc(a.castName)}</b></p>`:''}<ol class="project-stages">${stages(a)}</ol><div class="project-plan-progress"><progress max="100" value="${progress(a.progressPercent)}" aria-label="ความคืบหน้าบทปัจจุบัน"></progress><span>${progress(a.progressPercent)}%</span></div><p class="project-status-text" role="status">${esc(activeStatus(a))}</p><p class="life-small-note">ให้เวลากับ ${esc(a.focusLabels||'เป้าหมายที่เกี่ยวข้อง')}${a.costPerQuarter?' · ค่าใช้จ่ายพื้นฐาน '+number(a.costPerQuarter)+' '+(a.costUnit||'ทอง')+'ต่อช่วงวัย':''}<br>การฝึกและค่าใช้จ่ายปรับตามอายุขัยของเผ่า การเปลี่ยนโฟกัสไม่ลบสิ่งที่ทำไปแล้ว</p><div class="project-actions">${!a.supported&&!s.dead?'<button class="secondary" id="projectFocus">ปรับโฟกัสปีนี้ →</button>':''}<button class="secondary" id="projectCancel" ${locked?'disabled':''}>พักเรื่องนี้และเลือกทางใหม่</button></div></section>`:''}<h3 class="life-subtitle">${a?'เส้นทางอื่นในโลกนี้':'เลือกเรื่องที่อยากเริ่ม'}</h3><div class="project-catalog">${choices.map(p=>`<article class="project-option ${p.active?'active':p.completed?'completed':''}"><div class="project-option-heading"><h3>${esc(p.name)}</h3><span>${p.active?'กำลังทำ':p.completed?'จบเรื่องแล้ว':p.paused?'พักไว้':p.available?'เริ่มได้ตอนนี้':'รอโอกาส'}</span></div><p>${esc(p.description)}</p><small>${esc(requirementsText(p))}</small>${p.costPerQuarter?`<small>ค่าใช้จ่ายพื้นฐาน ${number(p.costPerQuarter)} ${p.costUnit||'ทอง'}ต่อช่วงวัย</small>`:'<small>ไม่มีค่าใช้จ่ายประจำของเส้นทาง</small>'}${p.reason&&!p.available?`<small class="project-option-reason">${esc(p.reason)}</small>`:''}<button class="secondary" data-start-project="${esc(p.id)}" ${locked||!p.available?'disabled':''}>${p.active?'กำลังทำเรื่องนี้':p.completed?'เก็บไว้ในเรื่องราวแล้ว':p.paused?'กลับมาทำต่อ →':'เริ่มเรื่องนี้ →'}</button></article>`).join('')}</div>${report.completed?.length?`<h3 class="life-subtitle">บทจบที่คุณเลือก</h3><ol class="project-completed">${report.completed.map(c=>`<li><small>อายุ ${number(c.age)} ปี</small><b>${esc(c.name||LifeProjects.catalog.find(p=>p.id===c.id)?.name||'เรื่องหนึ่งในชีวิต')}</b><p>${esc(c.endingLabel||c.ending||'จบเรื่องราวนี้ตามทางที่คุณเลือก')}</p></li>`).join('')}</ol>`:''}${report.history?.length?`<details class="project-history"><summary>รอยทางของเรื่องนี้</summary><ol>${report.history.slice(0,16).map(h=>`<li><small>อายุ ${number(h.age)} ปี</small><span>${esc(h.text)}</span></li>`).join('')}</ol></details>`:''}<p class="life-small-note">เส้นทางที่ยังไม่พร้อมจะเปิดเมื่อวัย อาชีพ ของใช้ และเรื่องที่เกิดขึ้นในชีวิตตรงเงื่อนไข</p></div>`);
 document.querySelectorAll('[data-start-project]').forEach(button=>button.onclick=()=>{if(LifeProjects.start(state,button.dataset.startProject))refresh('เริ่มเรื่องที่อยากทำแล้ว')});
 if($('#projectCancel'))$('#projectCancel').onclick=confirmCancel;
 if($('#projectFocus'))$('#projectFocus').onclick=()=>LifeUI.focus();
 }
 function confirmCancel(){const a=LifeProjects.summary(state).active;if(!a)return;modal(`<div class="life-dialog project-dialog"><h2>พักเรื่อง ${esc(a.name)} ไว้ก่อน?</h2><p>ความคืบหน้าและทางที่เลือกจะเก็บไว้ คุณกลับมาทำต่อจากบทเดิมได้ เวลาและค่าใช้จ่ายที่ผ่านมาไม่ได้คืน แต่ช่วงที่พักไว้จะไม่เดินหน้าต่อ</p><div class="project-actions"><button class="secondary" id="projectKeep">ทำเรื่องนี้ต่อ</button><button class="secondary" id="projectConfirmCancel">พักเรื่องนี้และเลือกทางใหม่</button></div></div>`);$('#projectKeep').onclick=open;$('#projectConfirmCancel').onclick=()=>{if(LifeProjects.cancel(state))refresh('พักเรื่องนี้ไว้และเก็บความคืบหน้าแล้ว');else open()}}
 return {panel,bind,open};
})();
